{
  "findings": [
    {
      "ref": "[D538]",
      "area": "contact",
      "claim": "A parent reports that strangers can message or voice chat with your child on Roblox.",
      "stance": "risk",
      "quote": "Some Roblox experiences support voice chat for eligible users. Access to certain communication features may require age verification, and parents should review communication settings regularly and discuss safe online interactions with children."
    },
    {
      "ref": "[D538]",
      "area": "money",
      "claim": "Roblox encourages in-app purchases of Robux that can lead to unexpected spending.",
      "stance": "risk",
      "quote": "Children can purchase Robux, Roblox’s virtual currency, and spend it on items, upgrades and experiences. Parents can use spending controls to help manage purchases."
    },
    {
      "ref": "[D538]",
      "area": "data",
      "claim": "Roblox collects personal data and may share it with third parties for advertising, and the data can be deleted through account settings.",
      "stance": "neutral",
      "quote": "Roblox also uses age assurance and verification measures for some features, alongside parental controls and content restrictions, to help create age‑appropriate experiences for younger users."
    },
    {
      "ref": "[D538]",
      "area": "age_gating",
      "claim": "A parent reports that Roblox’s age‑gating works in practice, assigning users to Roblox Kids accounts based on the age they input.",
      "stance": "mitigation",
      "quote": "Users are automatically assigned to an account type based off the age they input when creating a profile. Anyone who doesn’t verify their age is assigned to a Roblox Kids account."
    },
    {
      "ref": "[D538]",
      "area": "content",
      "claim": "A parent reports that children may see scams offering free Robux or exclusive items that appear genuine but are designed to steal account details.",
      "stance": "risk",
      "quote": "On Roblox, children may come across promises of free Robux, exclusive items or special game benefits that look genuine but are designed to steal account details or personal information."
    },
    {
      "ref": "[D538]",
      "area": "developer_record",
      "claim": "A parent reports that Roblox has faced regulatory scrutiny and restrictions, such as additional restrictions for UK users under 18 around paid random items.",
      "stance": "risk",
      "quote": "Roblox has introduced additional restrictions for UK users under 18 around experiences that include paid random items, helping to limit younger users’ exposure to gambling‑like mechanics."
    }
  ]
}
